<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {dailyBookingApi} from '../api'
import type{DailyBooking,DailyBookingInput,DailyOptions}from'../types'
const props=defineProps<{bookingId?:number}>(),router=useRouter()
const options=ref<DailyOptions|null>(null),loading=ref(false),saving=ref(false),error=ref(''),errors=ref<Record<string,string[]>>({})
const form=reactive<DailyBookingInput>({guest_company_name:'',car_id:null,custom_car_name:'',secondary_car_id:null,driver_id:null,custom_driver_name:'',operator_id:0,even_odd:'Even',start_date:'',end_date:'',status:'Confirm',remark:''})
function assign(b:DailyBooking){Object.assign(form,{guest_company_name:b.guest_company_name,car_id:b.car_id,custom_car_name:b.custom_car_name||'',secondary_car_id:b.secondary_car_id,driver_id:b.driver_id,custom_driver_name:b.custom_driver_name||'',operator_id:b.operator_id||0,even_odd:b.even_odd||'Even',start_date:b.start_date,end_date:b.end_date,status:b.status,remark:b.remark||''})}
onMounted(async()=>{loading.value=true;try{options.value=await dailyBookingApi.options();if(props.bookingId)assign(await dailyBookingApi.get(props.bookingId))}catch(e:any){error.value=e?.response?.data?.message||'Unable to load booking form.'}finally{loading.value=false}})
async function submit(){saving.value=true;errors.value={};error.value='';try{const saved=await dailyBookingApi.save(form,props.bookingId);await router.push(`/daily-bookings/${saved.id}`)}catch(e:any){errors.value=e?.response?.data?.errors||{};error.value=e?.response?.data?.message||'Unable to save booking.'}finally{saving.value=false}}
</script>
<template><div v-if="loading" class="alert alert-light border">Loading booking information…</div><div v-else><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><form class="card shadow-sm" @submit.prevent="submit"><div class="card-body"><div class="row g-3">
<div class="col-md-6"><label for="booking-guest" class="form-label">Guest / company</label><input id="booking-guest" v-model="form.guest_company_name" class="form-control" required><div v-if="errors.guest_company_name" class="text-danger small">{{errors.guest_company_name[0]}}</div></div>
<div class="col-md-6"><label for="booking-operator" class="form-label">Operator</label><select id="booking-operator" v-model.number="form.operator_id" class="form-select" required><option :value="0">Choose active operator</option><option v-for="o in options?.operators||[]" :key="o.id" :value="o.id">{{o.full_name}}</option></select><div v-if="errors.operator_id" class="text-danger small">{{errors.operator_id[0]}}</div></div>
<div class="col-md-6"><label for="booking-car" class="form-label">Primary vehicle</label><select id="booking-car" v-model="form.car_id" class="form-select"><option :value="null">No registered vehicle</option><option v-for="c in options?.cars||[]" :key="c.id" :value="c.id" :disabled="c.availability_status==='Maintenance'">{{c.plate_no}} · {{c.model_name}} ({{c.availability_status}})</option></select><div v-if="errors.car_id" class="text-danger small">{{errors.car_id[0]}}</div></div>
<div class="col-md-6"><label for="booking-car-custom" class="form-label">Other vehicle description</label><input id="booking-car-custom" v-model="form.custom_car_name" class="form-control"></div>
<div class="col-md-6"><label for="booking-car-second" class="form-label">Second vehicle</label><select id="booking-car-second" v-model="form.secondary_car_id" class="form-select"><option :value="null">None</option><option v-for="c in options?.cars||[]" :key="c.id" :value="c.id" :disabled="c.availability_status==='Maintenance'||c.id===form.car_id">{{c.plate_no}} · {{c.model_name}}</option></select><div v-if="errors.secondary_car_id" class="text-danger small">{{errors.secondary_car_id[0]}}</div></div>
<div class="col-md-6"><label for="booking-driver" class="form-label">Driver</label><select id="booking-driver" v-model="form.driver_id" class="form-select"><option :value="null">No registered driver</option><option v-for="d in options?.drivers||[]" :key="d.id" :value="d.id" :disabled="['Leave','Inactive'].includes(d.driver_status)">{{d.full_name}} ({{d.driver_status}})</option></select><div v-if="errors.driver_id" class="text-danger small">{{errors.driver_id[0]}}</div></div>
<div class="col-md-6"><label for="booking-driver-custom" class="form-label">Other driver description</label><input id="booking-driver-custom" v-model="form.custom_driver_name" class="form-control"></div>
<div class="col-md-3"><label for="booking-evenodd" class="form-label">Even / odd</label><select id="booking-evenodd" v-model="form.even_odd" class="form-select" required><option>Even</option><option>Odd</option></select></div><div class="col-md-3"><label for="booking-status" class="form-label">Status</label><select id="booking-status" v-model="form.status" class="form-select"><option v-for="s in options?.statuses||['Pending','Confirm','Completed','Cancelled']" :key="s">{{s}}</option></select><div v-if="errors.status" class="text-danger small">{{errors.status[0]}}</div></div>
<div class="col-md-3"><label for="booking-start" class="form-label">Start date</label><input id="booking-start" v-model="form.start_date" type="date" class="form-control" required><div v-if="errors.start_date" class="text-danger small">{{errors.start_date[0]}}</div></div><div class="col-md-3"><label for="booking-end" class="form-label">End date</label><input id="booking-end" v-model="form.end_date" type="date" class="form-control" required><div v-if="errors.end_date" class="text-danger small">{{errors.end_date[0]}}</div></div>
<div class="col-12"><label for="booking-remark" class="form-label">Remark</label><textarea id="booking-remark" v-model="form.remark" class="form-control" rows="3"/></div></div></div><div class="card-footer bg-white d-flex justify-content-end gap-2"><RouterLink to="/daily-bookings" class="btn btn-outline-secondary">Cancel</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Saving…':'Save booking'}}</button></div></form></div></template>
